// Builds a process queue from arrays of process data (ID).
node* helper_build_process_queue(int *ids, int *ats, int *bts, int *priorities, int size) {
    node *root = NULL;
    for (int i = 0; i < size; i++) {
        // Simulate insert by creating nodes manually
        node *new_node = (node*)malloc(sizeof(node));
        new_node->ID = ids[i];
        new_node->AT = ats[i];
        new_node->BT = bts[i];
        new_node->priority = priorities[i];
        new_node->CT = 0;
        new_node->WT = 0;
        new_node->TAT = 0;
        new_node->next = NULL;

        if (root == NULL) {
            root = new_node;
        } else {
            node *ptr = root;
            while (ptr->next != NULL) {
                ptr = ptr->next;
            }
            ptr->next = new_node;
        }
    }
    return root;
}

// Frees all nodes in a process queue.
void helper_cleanup_process_queue(node **root) {
    if (root == NULL || *root == NULL) {
        return;
    }
    node *current = *root;
    node *next;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    *root = NULL;
}
